function simpleManagementPanel(title,description,emptyText){const programs=title==="البرامج التدريبية",batches=title==="الدفعات التدريبية";const enrolled=cache.courses.reduce((n,c)=>n+(Number(c.trainee_count)||0),0);const items=programs?[["إجمالي البرامج",0,"▤","gold"],["الدورات التدريبية",cache.courses.length,"▣","teal"],["المحاضرون",cache.trainers.length,"♙","violet"],["إجمالي التسجيلات",enrolled,"♧","rose"]]:[["إجمالي الدفعات",0,"▤","gold"],["الدورات المرتبطة",cache.courses.length,"▣","teal"],["المتدربون المسجلون",enrolled,"♙","violet"],["المحاضرون",cache.trainers.length,"♧","rose"]];return `${head(title,description,me.role==="admin"?"course":null,programs?"إضافة برنامج":batches?"إضافة دفعة":"إضافة عنصر")}${summaryStats(items)}<section class="panel management-intro"><div class="management-icon">▤</div><h2>${title}</h2><p>${description}</p><div class="empty">${emptyText}</div><p class="management-note">الأرقام أعلاه محسوبة من بيانات الدورات والتسجيلات الحالية. لا توجد ${programs?"برامج":"دفعات"} محفوظة في قاعدة البيانات حتى الآن.</p></section>`}
function head(title,desc,btn,label){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${btn?`<button class="primary" data-open="${btn}">＋ ${label}</button>`:""}</div>`}
function dashboard(data){
 const s=data.stats||{};
 const total=cache.courses.length;
 const online=cache.courses.filter(c=>/online|أونلاين|اونلاين|عن بعد/i.test([c.title,c.description,c.delivery_mode,c.mode].filter(Boolean).join(" "))).length;
 const registrations=cache.courses.reduce((n,c)=>n+(Number(c.trainee_count)||0),0);
 const trainerRows=(cache.trainers||[]).map(t=>{const assigned=cache.courses.filter(c=>String(c.trainer_id||"")===String(t.id));return {...t,count:assigned.length,students:assigned.reduce((n,c)=>n+(Number(c.trainee_count)||0),0)}}).sort((a,b)=>b.students-a.students||b.count-a.count).slice(0,5);
 if(me.role!=="admin")return `${head("الرئيسية",me.role==="trainee"?"مساحتك التدريبية — تابع دوراتك وجلساتك من مكان واحد":"ملخص التدريب")}
 <section class="panel trainee-home-panel"><div class="section-heading"><div><h2>${me.role==="trainer"?"دوراتك الحالية":"دوراتي التدريبية"}</h2><p>${me.role==="trainer"?"الدورات المسندة إليك ومتابعة المتدربين":"الدورات التي تم تسجيلك بها رسميًا"}</p></div><span class="status-pill">${cache.courses.length} ${cache.courses.length===1?"دورة":"دورات"}</span></div>
 ${cache.courses.length?`<div class="cards">${cache.courses.map(courseCard).join("")}</div>`:`<div class="trainee-empty-state"><div class="trainee-empty-icon">▣</div><h3>لا توجد دورات مرتبطة بحسابك حتى الآن</h3><p>عند تسجيلك في دورة من إدارة المعهد، ستظهر هنا تفاصيلها والمحاضر والجلسات والمواد التدريبية المرتبطة بها.</p><div class="trainee-next-step"><strong>ماذا أفعل الآن؟</strong><span>تواصل مع إدارة المعهد للتأكد من ربط حسابك بملف المتدرب وتسجيلك في الدورة الصحيحة.</span></div></div>`}</section>
 ${me.role==="trainee"?`<div class="trainee-quick-links"><button class="panel trainee-quick-link" data-page="sessions"><span>▣</span><strong>الجلسات التدريبية</strong><small>مواعيد وروابط الجلسات المسجلة</small></button><button class="panel trainee-quick-link" data-page="library"><span>▤</span><strong>المكتبة التدريبية</strong><small>الوصول إلى المواد التدريبية المتاحة</small></button><button class="panel trainee-quick-link" data-page="tasks"><span>✓</span><strong>المهام</strong><small>متابعة الأنشطة المطلوبة منك</small></button></div>`:""}
 <footer class="dashboard-footer">الإدارة المركزية للتدريب · منصة التدريب والتعليم</footer>`;
 const metrics=[
  {label:"إجمالي الدورات التدريبية",value:s.courses??total,icon:"▤",tone:"gold"},
  {label:"دورات تدريبية أونلاين",value:online,icon:"▣",tone:"teal"},
  {label:"المحاضرون",value:s.trainers??cache.trainers.length,icon:"♙",tone:"violet"},
  {label:"إجمالي التسجيلات",value:registrations,icon:"♧",tone:"rose"}
 ];
 const chartCourses=cache.courses.slice(0,6);
 const max=Math.max(1,...chartCourses.map(c=>Number(c.trainee_count)||0));
 const bars=chartCourses.map((c,i)=>{const count=Number(c.trainee_count)||0;const height=Math.max(4,(count/max)*100);return `<div class="vbar-item" style="--bar-height:${height}%;--bar-delay:${i*120}ms"><b class="vbar-value">${count}</b><div class="vbar-column"><span></span></div><small title="${esc(c.title)}">${esc(c.title)}</small></div>`}).join("");
 return `${head("الرئيسية","ملخص التدريب")}
 <div class="stats dashboard-stats">${metrics.map(m=>`<article class="stat stat-modern"><div class="stat-top"><span>${m.label}</span><i class="stat-icon ${m.tone}">${m.icon}</i></div><strong>${m.value}</strong></article>`).join("")}</div>
 <div class="dashboard-chart-grid reference-dashboard-grid">
  <section class="panel chart-panel distribution-panel"><div class="section-heading"><div><h2>توزيع الدورات التدريبية</h2></div><span class="section-symbol">▣</span></div><div class="simple-donut-wrap"><div class="dash-donut simple-donut"><div><strong>${total}</strong><span>دورة</span></div></div><div class="simple-donut-legend"><i></i><span>عدد الدورات</span></div></div></section>
  <section class="panel chart-panel bar-chart-panel"><div class="section-heading"><div><h2>عدد المتدربين لكل دورة تدريبية</h2></div><span class="section-symbol">↗</span></div>${chartCourses.length?`<div class="vertical-chart"><div class="chart-y-axis"><span>${max}</span><span>${Math.round(max*.75)}</span><span>${Math.round(max*.5)}</span><span>${Math.round(max*.25)}</span><span>0</span></div><div class="vertical-chart-plot"><div class="chart-grid-lines"><i></i><i></i><i></i><i></i><i></i></div><div class="vertical-bars">${bars}</div></div></div>`:`<div class="empty">أضف دورة وابدأ تسجيل المتدربين لعرض الإحصائيات.</div>`}</section>
 </div>
 <section class="panel active-trainers-panel"><div class="section-heading"><div><h2>أكثر المحاضرين نشاطًا</h2></div></div>${trainerRows.length?`<div class="active-trainers-list">${trainerRows.map((t,i)=>`<div class="active-trainer-row"><span class="trainer-rank">${i+1}</span><div class="trainer-main"><b>${esc(t.name)}</b><small>${esc(t.specialty||"محاضر")}</small></div><div class="trainer-summary"><span>${t.count} دورة تدريبية</span><span>${t.students} متدرب</span></div></div>`).join("")}</div>`:`<div class="empty">ستظهر إحصائيات المحاضرين بعد إضافة المحاضرين وربطهم بالدورات.</div>`}</section>
 <footer class="dashboard-footer">الإدارة المركزية للتدريب · منصة التدريب والتعليم</footer>`
}
function reportsHub(data){if(me.role!=="admin")return '<div class="empty">التقارير التفصيلية متاحة لمدير النظام فقط.</div>';const links=[['report-platform','▥','تقارير المنصة','إجمالي الدورات والتسجيلات والمحاضرين والجلسات'],['report-courses','▤','تقارير الدورات التدريبية','أعداد المتدربين وتوزيع التسجيلات لكل دورة'],['report-trainers','♙','تقارير المحاضرين','الدورات المسندة وأعداد المتدربين لكل محاضر']];return `${head("تقارير وإحصائيات","اختر التقرير المطلوب لعرض تفاصيله في لوحة مستقلة.")}<div class="report-tiles">${links.map(([page,icon,title,desc])=>`<button class="report-tile" data-page="${page}"><span class="report-tile-icon">${icon}</span><b>${title}</b><small>${desc}</small><span class="report-open">فتح التقرير ←</span></button>`).join("")}</div>`}
function platformReport(data){if(me.role!=="admin")return '<div class="empty">التقرير متاح لمدير النظام فقط.</div>';const s=data.stats||{};const items=[['إجمالي الدورات',s.courses??cache.courses.length,'gold'],['إجمالي المتدربين',s.trainees??cache.trainees.length,'teal'],['المحاضرون',s.trainers??cache.trainers.length,'violet'],['الجلسات التدريبية',s.sessions??cache.sessions.length,'rose'],['طلبات الترشح',cache.applications.length,'gold'],['طلبات قيد المراجعة',cache.applications.filter(a=>a.status==='pending').length,'rose']];return `${head("تقارير المنصة","المؤشرات العامة في لوحة مستقلة.")}<div class="report-metric-grid">${items.map(([label,value,tone])=>`<article class="stat stat-modern"><div class="stat-top"><span>${label}</span><i class="stat-icon ${tone}">▣</i></div><strong>${value}</strong><small>حسب البيانات المسجلة حاليًا</small></article>`).join("")}</div><section class="panel report-panel"><div class="section-heading"><div><h2>ملخص حالة المنصة</h2><p>ملخص الأرقام المسجلة حاليًا</p></div></div><div class="report-summary-row"><span>الدورات التدريبية</span><b>${cache.courses.length}</b></div><div class="report-summary-row"><span>الدورات التي لها تسجيلات</span><b>${cache.courses.filter(c=>Number(c.trainee_count)>0).length}</b></div><div class="report-summary-row"><span>طلبات الترشح المقبولة</span><b>${cache.applications.filter(a=>a.status==='approved').length}</b></div></section>`}
function courseReport(data){if(me.role!=="admin")return '<div class="empty">التقرير متاح لمدير النظام فقط.</div>';const max=Math.max(1,...cache.courses.map(c=>Number(c.trainee_count)||0));const bars=cache.courses.map(c=>`<div class="dash-bar-row report-bar-row"><div class="dash-bar-label" title="${esc(c.title)}">${esc(c.title)}</div><div class="dash-bar-track"><span style="--bar-width:${Math.max(0,((Number(c.trainee_count)||0)/max)*100)}%"></span></div><b>${Number(c.trainee_count)||0}</b></div>`).join("");return `${head("تقارير الدورات التدريبية","تفاصيل كل دورة وعدد المتدربين المسجلين بها.")}<section class="panel report-panel"><div class="section-heading"><div><h2>عدد المتدربين لكل دورة</h2><p>تظهر الأعمدة بحركة تدريجية عند فتح التقرير.</p></div></div>${cache.courses.length?`<div class="dash-bars animated-bars">${bars}</div>`:'<div class="empty">لا توجد دورات مسجلة لعرض التقرير.</div>'}</section><section class="panel report-panel"><div class="section-heading"><div><h2>تفاصيل الدورات</h2><p>بيانات الدورة والتسجيلات الحالية</p></div></div>${cache.courses.length?`<div class="table-wrap"><table><thead><tr><th>الدورة</th><th>المحاضر</th><th>عدد المتدربين</th><th>السعة</th><th>تاريخ البداية</th></tr></thead><tbody>${cache.courses.map(c=>`<tr><td>${esc(c.title)}</td><td>${esc(c.trainer_name||'غير محدد')}</td><td>${Number(c.trainee_count)||0}</td><td>${c.capacity??'—'}</td><td>${esc(c.starts_on||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">لا توجد بيانات.</div>'}</section>`}
function trainerReport(data){if(me.role!=="admin")return '<div class="empty">التقرير متاح لمدير النظام فقط.</div>';const rows=cache.trainers.map(t=>{const assigned=cache.courses.filter(c=>String(c.trainer_id||'')===String(t.id));return {...t,count:assigned.length,students:assigned.reduce((n,c)=>n+(Number(c.trainee_count)||0),0)}}).sort((a,b)=>b.students-a.students||b.count-a.count);return `${head("تقارير المحاضرين","لوحة مستقلة لنشاط المحاضرين والدورات المسندة.")}<section class="panel report-panel"><div class="section-heading"><div><h2>المحاضرون الأكثر نشاطًا</h2><p>الترتيب حسب عدد المتدربين ثم الدورات المسندة</p></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>الترتيب</th><th>المحاضر</th><th>التخصص</th><th>الدورات المسندة</th><th>إجمالي المتدربين</th></tr></thead><tbody>${rows.map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.name)}</td><td>${esc(t.specialty||'—')}</td><td>${t.count}</td><td>${t.students}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">أضف محاضرين واربطهم بالدورات لعرض التقرير.</div>'}</section>`}
function courseCard(c){
 const enabled = value => value === true || value === 1 || value === "1" || String(value ?? "").trim().toLowerCase() === "true" || String(value ?? "").trim().toLowerCase() === "yes" || String(value ?? "").trim().toLowerCase() === "on";
 const testActive=enabled(c.test_enabled)&&Boolean(String(c.test_url||"").trim());
 const evaluationActive=enabled(c.evaluation_enabled)&&Boolean(String(c.evaluation_url||"").trim());
 const activityLinks=((String(me.role||"").toLowerCase()==="admin"||String(me.role||"").toLowerCase()==="trainee")&&(testActive||evaluationActive))?`<div class="course-link-panel"><div class="course-link-panel-title">روابط الدورة المتاحة</div><div class="course-link-actions">${testActive?`<a class="tiny course-link-btn" href="${esc(c.test_url)}" target="_blank" rel="noopener noreferrer">▣ فتح اختبار الدورة ↗</a>`:""}${evaluationActive?`<a class="tiny course-link-btn course-evaluation-btn" href="${esc(c.evaluation_url)}" target="_blank" rel="noopener noreferrer">☆ تقييم الدورة ↗</a>`:""}</div>${testActive&&c.test_password?`<div class="course-password-box"><label for="course-password-${c.id}">كلمة مرور الاختبار</label><div class="course-password-row"><input id="course-password-${c.id}" type="password" value="${esc(c.test_password)}" readonly autocomplete="off"><button type="button" class="tiny" data-reveal-password="${c.id}" aria-label="إظهار كلمة مرور الاختبار">إظهار</button><button type="button" class="tiny" data-copy-password="${c.id}">نسخ</button></div></div>`:""}</div>`:"";
 return `<article class="card course-card-pro"><div class="course-card-title"><span class="course-icon">▣</span><div><h3>${esc(c.title)}</h3><small>${esc(c.trainer_name||"لم يحدد محاضر بعد")}</small></div></div><div class="meta"><span>المتدربون: <b>${Number(c.trainee_count)||0}${c.capacity?` / ${c.capacity}`:""}</b></span><span>البداية: ${esc(c.starts_on||"لم تحدد")}</span><span>النهاية: ${esc(c.ends_on||"لم تحدد")}</span></div>${c.description?`<p>${esc(c.description)}</p>`:""}<p class="muted">${Number(c.public_registration_enabled)===0?"غير ظاهرة في الشاشة الافتتاحية":"متاحة للتسجيل من الشاشة الافتتاحية"}</p>${activityLinks}<div class="course-actions"><button class="tiny" data-show-trainees="${c.id}">♧ بيانات المتدربين (${Number(c.trainee_count)||0})</button>${me.role==="admin"?`<button class="tiny" data-admin-record="courses" data-record-id="${c.id}">تعديل الدورة</button><button class="tiny" data-enroll="${c.id}">＋ تسجيل متدرب</button><button class="tiny course-settings-btn" data-course-links="${c.id}">⚙ إعداد الاختبار والتقييم</button><button class="tiny ${Number(c.public_registration_enabled)===1?"":"outline"}" data-course-visibility="${c.id}" data-enabled="${Number(c.public_registration_enabled)===1?"1":"0"}">${Number(c.public_registration_enabled)===1?"✓ ظاهرة بالخطة — إخفاء":"إظهار في الخطة"}</button>`:""}<button class="tiny" data-page="tasks">▣ إدارة المحتوى</button><button class="tiny" data-page="sessions">◉ دردشة / جلسات الدورة</button><button class="tiny" data-page="attendance">◷ الجدول الزمني / الحضور</button><button class="tiny" data-page="training-plan">▧ الخطة التدريبية</button>${me.role==="admin"?`<button class="tiny danger" data-delete="course" data-id="${c.id}">حذف الدورة</button>`:""}</div></article>`
}
function coursesPage(){const registrations=cache.courses.reduce((n,c)=>n+(Number(c.trainee_count)||0),0);const online=cache.courses.filter(c=>/online|أونلاين|اونلاين|عن بعد/i.test([c.title,c.description,c.delivery_mode,c.mode].filter(Boolean).join(" "))).length;return `${head("الدورات التدريبية","إنشاء الدورات وربط المحاضرين والمتدربين",me.role==="admin"?"course":null,"إضافة دورة")}${summaryStats([["إجمالي الدورات التدريبية",cache.courses.length,"▤","gold"],["دورات تدريبية أونلاين",online,"▣","teal"],["المحاضرون",cache.trainers.length,"♙","violet"],["إجمالي التسجيلات",registrations,"♧","rose"]])}${cache.courses.length?`<div class="cards">${cache.courses.map(courseCard).join("")}</div>`:`<div class="empty">لا توجد دورات متاحة.</div>`}`}
function traineesPage(){return `${head("المتدربون","بيانات المتدربين المسجلين",me.role==="admin"?"trainee":null,"إضافة متدرب")}<div class="admin-search"><input id="traineeSearch" type="search" placeholder="ابحث بالاسم أو الهاتف أو البريد أو اسم المستخدم…" aria-label="البحث في المتدربين"></div><div class="table-wrap"><table id="traineesTable"><thead><tr><th>الاسم</th><th>الهاتف</th><th>البريد</th><th>القسم / الجهة</th>${me.role==="admin"?"<th>إجراء</th>":""}</tr></thead><tbody>${cache.trainees.map(t=>`<tr data-search="${esc([t.name,t.phone,t.email,t.department,t.username].join(" ").toLowerCase())}"><td>${esc(t.name)}</td><td>${esc(t.phone||"—")}</td><td>${esc(t.email||"—")}</td><td>${esc(t.department||"—")}</td>${me.role==="admin"?`<td><div class="actions"><button class="tiny" data-mail-credentials="${t.id}">إرسال بيانات الدخول</button><small title="${esc(t.credential_email_error||'')}">${t.credential_email_status==='sent'?'تم إرسال البريد':t.credential_email_status==='failed'?'تعذر إرسال البريد':'البريد لم يرسل'}</small><button class="tiny" data-edit="trainee" data-id="${t.id}">تعديل</button><button class="tiny danger" data-delete="trainee" data-id="${t.id}">حذف</button></div></td>`:""}</tr>`).join("")}</tbody></table></div>${cache.trainees.length?"":'<div class="empty">لا توجد بيانات متدربين.</div>'}`}

function trainersPage(){if(me.role!=="admin")return `<div class="empty">ليس لديك صلاحية لعرض بيانات المحاضرين.</div>`;return `${head("المحاضرون","إضافة محاضر، مع إمكانية إنشاء حساب دخول له", "trainer","إضافة محاضر")}<div class="admin-search"><input id="trainerSearch" type="search" placeholder="ابحث بالاسم أو التخصص أو الهاتف أو البريد…" aria-label="البحث في المحاضرين"></div><div class="table-wrap"><table id="trainersTable"><thead><tr><th>الاسم</th><th>التخصص</th><th>الهاتف</th><th>البريد</th><th>إجراء</th></tr></thead><tbody>${cache.trainers.map(t=>`<tr data-search="${esc([t.name,t.specialty,t.phone,t.email,t.username].join(" ").toLowerCase())}"><td>${esc(t.name)}</td><td>${esc(t.specialty||"—")}</td><td>${esc(t.phone||"—")}</td><td>${esc(t.email||"—")}</td><td><div class="actions"><button class="tiny" data-edit="trainer" data-id="${t.id}">تعديل</button><button class="tiny danger" data-delete="trainer" data-id="${t.id}">حذف</button></div></td></tr>` ).join("")}</tbody></table></div>${cache.trainers.length?"":'<div class="empty">لا يوجد محاضرون.</div>'}`}
function sessionsPage(){const now=new Date(),upcoming=cache.sessions.filter(s=>new Date(s.starts_at)>=now).length,past=cache.sessions.length-upcoming,linked=cache.sessions.filter(s=>s.url).length;return `${head("البث المباشر","المواعيد وروابط الاجتماعات الخارجية",(me.role==="admin"||me.role==="trainer")?"session":null,"إضافة جلسة")}${summaryStats([["إجمالي الجلسات",cache.sessions.length,"◉","gold"],["جلسات قادمة",upcoming,"◷","teal"],["جلسات انتهت",past,"✓","violet"],["روابط البث المضافة",linked,"↗","rose"]])}${cache.sessions.length?`<div class="cards">${cache.sessions.map(s=>`<article class="card"><h3>${esc(s.title)}</h3><div class="meta"><span>الدورة: ${esc(s.course_title)}</span><span>الموعد: ${esc(s.starts_at)}</span><span>المدة: ${s.duration} دقيقة — ${esc(s.platform)}</span><span>الحالة: ${new Date(s.starts_at)>=now?"قادمة":"انتهت"}</span></div>${me.role==="admin"?`<button class="tiny" data-admin-record="sessions" data-record-id="${s.id}">تعديل الجلسة</button>`:""}${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">فتح رابط الاجتماع ↗</a>`:"<p>لم يضف رابط الاجتماع بعد.</p>"}</article>`).join("")}</div>`:`<div class="empty">لا توجد جلسات مجدولة. استخدم «إضافة جلسة» لإنشاء أول موعد بث مباشر.</div>`}`}
function applicationsPage(){if(me.role!=="admin")return '<div class="empty">هذه الصفحة للمدير فقط.</div>';const rows=cache.applications||[];const pending=rows.filter(a=>a.status==="pending").length;const statusLabel={pending:"قيد المراجعة",approved:"مقبول",rejected:"مرفوض"};return `${head("طلبات الترشح","راجع الطلبات الواردة من واجهة الموقع؛ قبول الطلب يضيف المتدرب إلى سجل المتدربين ويسجله في الدورة.")}<div class="stats"><div class="stat"><span>إجمالي الطلبات</span><strong>${rows.length}</strong></div><div class="stat"><span>قيد المراجعة</span><strong>${pending}</strong></div><div class="stat"><span>مقبولة</span><strong>${rows.filter(a=>a.status==="approved").length}</strong></div><div class="stat"><span>مرفوضة</span><strong>${rows.filter(a=>a.status==="rejected").length}</strong></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>مقدم الطلب</th><th>التواصل</th><th>الدورة</th><th>تاريخ الطلب</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.applicant_name)}</td><td>${esc(a.phone)}<br><small>${esc(a.email)}</small></td><td>${esc(a.course_title)}</td><td>${esc(a.created_at)}${a.has_attachment?`<br><a href="/api/applications/${a.id}/attachment" target="_blank" rel="noopener">تحميل المرفق: ${esc(a.attachment_name||"ملف")}</a>`:""}</td><td><span class="status-pill status-${a.status}">${statusLabel[a.status]}</span>${a.trainee_name?`<br><small>المتدرب: ${esc(a.trainee_name)}</small>`:""}</td><td><div class="actions">${a.status==="pending"?`<button class="tiny" data-application-action="approved" data-id="${a.id}">قبول وإضافة</button><button class="tiny danger" data-application-action="rejected" data-id="${a.id}">رفض</button>`:""}${a.status!=="approved"?`<button class="tiny" data-admin-record="applications" data-record-id="${a.id}">تعديل الطلب</button>`:""}<button class="tiny danger" data-application-delete="${a.id}">حذف الطلب</button></div></td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">لا توجد طلبات ترشح حتى الآن. الطلبات التي يرسلها المتدرب من الشاشة الافتتاحية ستظهر هنا.</div>'}`}
function attendancePage(){if(me.role==="trainee")return `${head("الحضور اليومي","سجل حضورك في الدورات المسجل بها") }<section class="panel"><div class="activity-empty"><div class="activity-empty-icon">◷</div><h3>سجل الحضور الشخصي</h3><p>يمكنك متابعة سجل حضورك من حسابك. إذا لم تظهر سجلات، فقد لا تكون سجلات الحضور قد أُدخلت بعد.</p><button class="primary" id="loadMyAttendance">عرض سجل حضوري</button></div><div id="myAttendanceResult"></div></section>`;if(me.role!=="admin"&&me.role!=="trainer")return '<div class="empty">هذه الصفحة غير متاحة لحسابك.</div>';return `${head("الحضور اليومي","اختر دورة وتاريخًا لتسجيل الحضور")}<form id="attendanceForm" class="panel"><div class="field-grid"><div class="field"><label>الدورة</label><select name="course_id" required>${cache.courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join("")}</select></div><div class="field"><label>التاريخ</label><input type="date" name="date" value="${new Date().toISOString().slice(0,10)}" required></div></div><button class="primary" style="margin-top:12px">عرض سجل الحضور</button></form><div id="attendanceResult" style="margin-top:15px"></div>`}
function openForm(type){if(me.role!=="admin")return showMessage("هذه العملية للمدير فقط.");let title="",fields="";
const select=(name,label,opts)=>`<div class="field"><label>${label}</label><select name="${name}" required>${opts.map(o=>`<option value="${o.value}">${esc(o.label)}</option>`).join("")}</select></div>`;
const inp=(name,label,type="text",full=false,required=true,help="")=>`<div class="field ${full?"full":""}"><label>${label}</label><input name="${name}" type="${type}" ${required?"required":""}>${help?`<small>${help}</small>`:""}</div>`;
if(type==="trainee"){title="إضافة متدرب";fields=inp("name","اسم المتدرب")+inp("phone","رقم الهاتف","tel",false,false)+inp("email","البريد الإلكتروني","email",false,false)+inp("department","القسم / جهة العمل","text",false,false)+inp("username","اسم مستخدم لحساب المتدرب","text",true,false,"للمتدرب: اتركه فارغاً لتوليد بيانات دخول تلقائياً وإرسالها للبريد بعد تهيئة Google.")+inp("password","كلمة مرور حساب المتدرب","password",true,false,"للمتدرب: تُولَّد كلمة مرور قوية تلقائياً إذا تركت الحقل فارغاً. أو أدخل 12 حرفاً على الأقل.")}
if(type==="trainer"){title="إضافة محاضر";fields=inp("name","اسم المحاضر")+inp("specialty","التخصص","text",false,false)+inp("phone","رقم الهاتف","tel",false,false)+inp("email","البريد الإلكتروني","email",false,false)+inp("username","اسم مستخدم لحساب المحاضر","text",true,false,"للمتدرب: اتركه فارغاً لتوليد بيانات دخول تلقائياً وإرسالها للبريد بعد تهيئة Google.")+inp("password","كلمة مرور حساب المحاضر","password",true,false,"للمتدرب: تُولَّد كلمة مرور قوية تلقائياً إذا تركت الحقل فارغاً. أو أدخل 12 حرفاً على الأقل.")}
if(type==="course"){title="إضافة دورة";fields=inp("title","اسم الدورة","text",true)+`<div class="field full"><label>الوصف</label><textarea name="description" rows="3"></textarea></div>`+select("trainer_id","المحاضر",[{value:"",label:"بدون محاضر"},...cache.trainers.map(t=>({value:t.id,label:t.name}))])+inp("starts_on","تاريخ البداية","date",false,false)+inp("ends_on","تاريخ النهاية","date",false,false)+inp("capacity","العدد المستهدف","number",false,false)+`<div class="field full"><label class="switch-label"><input type="checkbox" name="public_registration_enabled" value="true" checked> إتاحة الدورة في الشاشة الافتتاحية وخطة الدورات والتسجيل</label><small class="muted">أزل العلامة لإبقاء الدورة داخل لوحة الإدارة فقط.</small></div>`}
if(type==="session"){title="إضافة جلسة بث مباشر";fields=inp("title","عنوان الجلسة","text",true)+select("course_id","الدورة",cache.courses.map(c=>({value:c.id,label:c.title})))+inp("starts_at","موعد البداية","datetime-local")+inp("duration","المدة بالدقائق","number",false,true)+select("platform","منصة الاجتماع",[{value:"Microsoft Teams",label:"Microsoft Teams"},{value:"Zoom",label:"Zoom"},{value:"Google Meet",label:"Google Meet"}])+inp("url","رابط الاجتماع","url",true,false,"الصق رابط الاجتماع الحقيقي.")}
$("#modalRoot").innerHTML=`<div class="modal-shade"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="outline" data-close>إغلاق ×</button></div><form id="dataForm"><div class="field-grid">${fields}</div><div class="modal-actions"><button type="button" class="outline" data-close>إلغاء</button><button class="primary">حفظ البيانات</button></div><p class="error" id="formError"></p></form></div></div>`;
if(type==="session"){$("#dataForm [name=duration]").value=60;const d=new Date(Date.now()+3600000);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());$("#dataForm [name=starts_at]").value=d.toISOString().slice(0,16)}
$("#dataForm").addEventListener("submit",async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));if(type==="course")body.public_registration_enabled=e.currentTarget.elements.public_registration_enabled.checked;try{let saveResult;if(type==="trainee")saveResult=await api("/trainees",{method:"POST",body:JSON.stringify(body)});if(type==="trainer")await api("/trainers",{method:"POST",body:JSON.stringify(body)});if(type==="course")await api("/courses",{method:"POST",body:JSON.stringify(body)});if(type==="session")await api("/sessions",{method:"POST",body:JSON.stringify(body)});$("#modalRoot").innerHTML="";await renderPage(currentPage);showMessage(saveResult?.message||"تم حفظ البيانات بنجاح.")}catch(err){$("#formError").textContent=err.message}});
}
function openCourseLinksForm(courseId){
 if(me.role!=="admin")return showMessage("إعداد روابط الاختبار والتقييم متاح لمدير النظام فقط.");
 const c=cache.courses.find(x=>Number(x.id)===courseId);if(!c)return showMessage("تعذر العثور على الدورة.");
 const checked=v=>Number(v)===1?"checked":"";
 $("#modalRoot").innerHTML=`<div class="modal-shade"><div class="modal modal-wide course-links-modal"><div class="modal-head"><div><h2>إعداد الاختبار والتقييم</h2><p class="muted">${esc(c.title)}</p></div><button class="outline" data-close>إغلاق ×</button></div><form id="courseLinksForm" class="form-grid">
 <section class="course-link-setting field-full"><div class="course-link-setting-head"><div><h3>اختبار الدورة</h3><p>أضف رابط الاختبار وكلمة المرور، ثم فعّل الإتاحة للمتدربين المسجلين في الدورة.</p></div><label class="switch-label"><input type="checkbox" name="test_enabled" value="1" ${checked(c.test_enabled)}> تفعيل الاختبار</label></div><div class="field"><label>رابط الاختبار</label><input name="test_url" type="url" inputmode="url" placeholder="https://..." value="${esc(c.test_url||"")}"></div><div class="field"><label>كلمة مرور الاختبار (اختياري)</label><div class="password-entry"><input id="admin-test-password" name="test_password" type="password" maxlength="128" autocomplete="off" placeholder="اكتب كلمة مرور الاختبار" value="${esc(c.test_password||"")}"><button type="button" class="tiny" data-toggle-admin-password="admin-test-password">إظهار</button></div><small class="muted">عند تفعيل الاختبار، تظهر كلمة المرور للمتدربين المسجلين بهذه الدورة.</small></div></section>
 <section class="course-link-setting field-full"><div class="course-link-setting-head"><div><h3>تقييم الدورة من المتدربين</h3><p>أضف رابط نموذج تقييم الدورة، ويمكنك تفعيله أو إيقافه في أي وقت.</p></div><label class="switch-label"><input type="checkbox" name="evaluation_enabled" value="1" ${checked(c.evaluation_enabled)}> تفعيل التقييم</label></div><div class="field"><label>رابط تقييم الدورة</label><input name="evaluation_url" type="url" inputmode="url" placeholder="https://..." value="${esc(c.evaluation_url||"")}"></div></section>
 <div class="modal-actions field-full"><button type="button" class="outline" data-close>إلغاء</button><button class="primary" type="submit">حفظ الإعدادات</button></div><p class="error field-full" id="courseLinksError"></p></form></div></div>`;
 const form=$("#courseLinksForm");form.querySelectorAll("[data-toggle-admin-password]").forEach(btn=>btn.addEventListener("click",()=>{const input=document.getElementById(btn.dataset.toggleAdminPassword);input.type=input.type==="password"?"text":"password";btn.textContent=input.type==="text"?"إخفاء":"إظهار"}));
 form.addEventListener("submit",async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.test_enabled=form.elements.test_enabled.checked;data.evaluation_enabled=form.elements.evaluation_enabled.checked;try{const result=await api(`/courses/${courseId}/links`,{method:"PATCH",body:JSON.stringify(data)});$("#modalRoot").innerHTML="";showMessage(result.message||"تم حفظ إعدادات الدورة.");await renderPage(currentPage)}catch(err){$("#courseLinksError").textContent=err.message}});
}
async function showCourseTrainees(courseId){const course=cache.courses.find(c=>Number(c.id)===courseId);if(!course)return;try{const rows=await api(`/courses/${courseId}/enrolled`);const roster=rows.length?`<div class="table-wrap"><table><thead><tr><th>اسم المتدرب</th><th>رقم الهاتف</th><th>الحالة</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.phone||"—")}</td><td><span class="status-pill">مسجل</span></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">لا يوجد متدربون مسجلون في هذه الدورة حتى الآن.</div>`;$("#modalRoot").innerHTML=`<div class="modal-shade"><div class="modal"><div class="modal-head"><h2>المتدربون — ${esc(course.title)}</h2><button class="outline" data-close>إغلاق ×</button></div><p class="muted">إجمالي المتدربين المسجلين: ${rows.length}</p>${roster}${me.role==="admin"?`<div class="modal-actions"><button class="primary" data-enroll="${courseId}">تسجيل متدرب جديد</button></div>`:""}</div></div>`;}catch(e){showMessage(e.message)}}
