async function toggleCourseVisibility(id, currentlyEnabled){const enabled=!currentlyEnabled;try{await api(`/courses/${id}/public-registration`,{method:"PATCH",body:JSON.stringify({enabled})});showMessage(enabled?"تم تفعيل ظهور الدورة في الشاشة الافتتاحية.":"تم إخفاء الدورة من الشاشة الافتتاحية.");await renderPage("courses")}catch(e){showMessage(e.message)}}
