 const form=$('#adminRecordForm');let targetLoading=false;
 async function targets(keep){targetLoading=true;try{const selected=keep?JSON.parse(item.trainee_ids||'[]'):[];const course=form.elements.course_id.value;const rows=course?await api(`/courses/${course}/enrolled`):[];$('#editTaskTargets').innerHTML=rows.map(t=>`<label class="choice-row"><input name="trainee_ids" type="checkbox" value="${t.id}" ${selected.includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join('')||'لا يوجد مسجلون.'}finally{targetLoading=false}}
