async function mailCredentials(id,button){if(!confirm('إرسال اسم المستخدم وكلمة المرور إلى بريد المتدرب المسجل؟'))return;button.disabled=true;try{const r=await api(`/trainees/${id}/send-credentials`,{method:'POST',body:'{}'});await renderPage(currentPage);showMessage(r.message)}catch(e){showMessage(e.message)}finally{button.disabled=false}}
