// A single touch-scrolling surface for dialogs; restore the previous focus after closing.
let dialogReturnFocus=null;
new MutationObserver(()=>{const shade=$('#modalRoot .modal-shade');document.body.classList.toggle('dialog-open',!!shade);if(shade&&!shade.dataset.accessible){dialogReturnFocus=document.activeElement;shade.dataset.accessible='1';const modal=shade.querySelector('.modal');modal?.setAttribute('role','dialog');modal?.setAttribute('aria-modal','true');const title=modal?.querySelector('h2');if(title){title.id='activeDialogTitle';modal.setAttribute('aria-labelledby',title.id)}shade.scrollTop=0;modal?.querySelector('input:not([type=hidden]),select,textarea,button')?.focus({preventScroll:true})}else if(!shade&&dialogReturnFocus){dialogReturnFocus.focus?.({preventScroll:true});dialogReturnFocus=null}}).observe($('#modalRoot'),{childList:true});
document.addEventListener('keydown',e=>{const modal=$('#modalRoot .modal');if(!modal)return;if(e.key==='Escape'){$('#modalRoot').innerHTML='';return}if(e.key==='Tab'){const controls=[...modal.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
